get() {
      counts[slot].getter++;
      trace.push(`primitive:get:${slot}`);
      native.call(`get:${slot}.toString`, this, value, []);
      if (["key-error", "orphan"].includes(scenario.kind) && scenario.slot === slot && scenario.phase === "primitive-get")
        throw errors.key;
      return function cacheKeyPrimitive(...args) {
        counts[slot].method++;
        trace.push(`primitive:call:${slot}`);
        native.call(`call:${slot}.toString`, this, value, args);
        assert.equal(this, value);
        assert.deepEqual(args, []);
        if (slot === "reference" && counts[slot].method > 1)
          throw errors.repeatedReference;
        if (["key-error", "orphan"].includes(scenario.kind) && scenario.slot === slot && scenario.phase === "primitive-call")
          throw errors.key;
        return suffixes[slot];
      };
    }

